//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::string::utf8_extract`; the
//! native twin is `benches/native/Bench/StringUtf8Extract.lean`.
//! the result is a new string object (allocated even when empty, its characters counted), as
//! lean_mk_string_from_bytes_unchecked makes

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::string;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &PosInput, n: u64) -> u64 {
    let (s, ps) = (inp.s.as_bytes(), &inp.ps[..]);
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            make_string(
                &s[string::utf8_extract(
                    s,
                    nat_unbox(get_word(ps, x >> 52)),
                    nat_unbox(get_word(ps, (x >> 40) & 4095)),
                )],
            )
            .byte_size(),
        );
    }
    acc
}

fn main() {
    run(|| pos_input(mixed(), Positions::Any), kernel)
}
